const wh = $('Sync Webhook').first().json;
const body = wh.body || wh;
const invoiceRows = Array.isArray(body.invoiceRows) ? body.invoiceRows : [];
const rows = invoiceRows.filter((r) => r && String(r.id || '').trim() !== '');
if (rows.length === 0) {
  return [{ json: { id: '', customer: '', email: '', phone: '', amountDue: 0, amountRemaining: 0, stage: 'queued' } }];
}
return rows.map((r) => ({ json: r }));

function istYmd(asOf) {
  const d = asOf || new Date();
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(d);
}
function parseSupplyDate(raw) {
  if (raw == null || raw === "") return null;
  if (typeof raw === "number" && Number.isFinite(raw)) {
    const ms = Math.round((raw - 25569) * 86400 * 1000);
    const d = new Date(ms);
    if (!Number.isFinite(d.getTime())) return null;
    return d.toISOString().slice(0, 10);
  }
  const s = String(raw).trim().replace(/^'/, "");
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const dmy = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
  if (dmy) {
    return dmy[3] + "-" + dmy[2].padStart(2, "0") + "-" + dmy[1].padStart(2, "0");
  }
  const t = Date.parse(s);
  if (Number.isFinite(t)) return new Date(t).toISOString().slice(0, 10);
  return null;
}
function addCalendarDays(ymd, days) {
  const parts = ymd.split("-").map(Number);
  const dt = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  dt.setUTCDate(dt.getUTCDate() + days);
  return dt.toISOString().slice(0, 10);
}
function diffCalendarDays(laterYmd, earlierYmd) {
  const a = laterYmd.split("-").map(Number);
  const b = earlierYmd.split("-").map(Number);
  return Math.round((Date.UTC(a[0], a[1] - 1, a[2]) - Date.UTC(b[0], b[1] - 1, b[2])) / 86400000);
}
function pickSupplyCredit(r) {
  const dateOfSupply = r.dateOfSupply ?? r["Date of supply"] ?? r["Date of Supply"] ?? r.DateOfSupply ?? r.date_of_supply ?? null;
  const creditDays = r.creditDays ?? r.creditLine ?? r["Credit line"] ?? r["Credit Line"] ?? r["Credit Days"] ?? r.credit_days ?? null;
  return { dateOfSupply, creditDays };
}
function deriveOverdue(r) {
  const picked = pickSupplyCredit(r);
  const supply = parseSupplyDate(picked.dateOfSupply);
  const creditRaw = picked.creditDays;
  const credit = creditRaw === "" || creditRaw == null ? null : Number(creditRaw);
  if (supply != null && credit != null && Number.isFinite(credit) && credit >= 0) {
    const dueDate = addCalendarDays(supply, Math.floor(credit));
    const today = istYmd(new Date());
    return {
      dateOfSupply: supply,
      creditDays: Math.floor(credit),
      dueDate,
      daysOverdue: Math.max(0, diffCalendarDays(today, dueDate)),
    };
  }
  const storedRaw = r["Days post due date "] ?? r.daysOverdue ?? r["Days post due date"] ?? 0;
  const stored = Number(storedRaw);
  return {
    dateOfSupply: supply,
    creditDays: credit != null && Number.isFinite(credit) ? Math.floor(credit) : null,
    dueDate: null,
    daysOverdue: Number.isFinite(stored) ? Math.max(0, Math.floor(stored)) : 0,
  };
}
function truthy(v) {
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const s = v.trim().toUpperCase();
    return s === "TRUE" || s === "1" || s === "YES";
  }
  return false;
}
const invoices = $input.all().map(({ json: r }) => {
const overdue = deriveOverdue(r);
const invoice = {
  id: String(r.id || ""),
  customer: String(r.customer || ""),
  email: String(r.email || ""),
  phone: String(r.phone || "").replace(/^'/, ""),
  amountDue: Number(r.amountDue || 0),
  amountRemaining: Number(r.amountRemaining || 0),
  dateOfSupply: overdue.dateOfSupply,
  creditDays: overdue.creditDays,
  dueDate: overdue.dueDate,
  daysOverdue: overdue.daysOverdue,
  stage: r.stage || "queued",
  classification: r.classification || null,
  replyText: r.repliedAt ? (r.replyText || "") : null,
  replyChannel: r.replyChannel || null,
  failureReason: r.failureReason || null,
  draftEmail: r.draftEmail || null,
  draftWhatsapp: r.draftWhatsapp || null,
  updatedAt: r.updatedAt || new Date().toISOString(),
  waStatus: r.waStatus || null,
  waOptIn: truthy(r.waOptIn),
  waOptOut: truthy(r.waOptOut),
};
  return invoice;
});
return [{ json: { invoices } }];

const invoices = $('Aggregate invoices').item.json.invoices || [];
const wh = $('Sync Webhook').first().json;
const body = wh.body || wh;
const inboundRows = Array.isArray(body.inboundRows) ? body.inboundRows : [];
let inbound = [];
try {
  inbound = inboundRows
    .map((r) => {
      if (!r || !r.sid) return null;
      const ts = r.timestamp ? Date.parse(String(r.timestamp)) : Date.now();
      return {
        sid: String(r.sid || ''),
        timestamp: Number.isFinite(ts) ? new Date(ts).toISOString() : String(r.timestamp || ''),
        from: String(r.from || ''),
        body: String(r.body || ''),
        kind: String(r.kind || 'reply'),
        suggestedInvoiceId: r.suggestedInvoiceId || null,
        attachedInvoiceId: r.attachedInvoiceId || null,
        status: String(r.status || 'pending').toLowerCase(),
        messageStatus: r.messageStatus || null,
        channel: r.channel === 'email' || r.channel === 'whatsapp' ? r.channel : null,
      };
    })
    .filter((e) => e && e.status === 'pending');
} catch (e) {
  inbound = [];
}
const syncedAt = body.syncedAt || new Date().toISOString();
return [{ json: { ok: true, invoices, inbound, syncedAt } }];

const ledger = $json;
const staticData = $getWorkflowStaticData('global');
staticData.ledger = {
  invoices: ledger.invoices || [],
  inbound: ledger.inbound || [],
  syncedAt: ledger.syncedAt || new Date().toISOString(),
};
return [{
  json: {
    ok: true,
    syncedAt: staticData.ledger.syncedAt,
    invoiceCount: staticData.ledger.invoices.length,
    inboundCount: staticData.ledger.inbound.length,
  },
}];

const staticData = $getWorkflowStaticData('global');
const ledger = staticData.ledger;
if (!ledger || !Array.isArray(ledger.invoices)) {
  return [{ json: { ok: false, error: 'ledger not synced yet', missing: true } }];
}
return [{
  json: {
    ok: true,
    invoices: ledger.invoices,
    inbound: ledger.inbound || [],
    syncedAt: ledger.syncedAt || null,
    missing: false,
  },
}];
